using Newtonsoft.Json.Linq;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Net;
using System.Text;

namespace autodealer.dev.Models {
    public static class PriceResearchHtmlRenderer {
        private static readonly CultureInfo Us=CultureInfo.GetCultureInfo("en-US");
        private static string E(object value){return WebUtility.HtmlEncode(Convert.ToString(value,CultureInfo.InvariantCulture)??string.Empty);}
        private static string Money(decimal? value){return value.HasValue?value.Value.ToString("C0",Us):"—";}
        private static string N(decimal? value,string format="N0"){return value.HasValue?value.Value.ToString(format,Us):"—";}
        private static string S(JObject row,string key){var token=row[key];return token==null||token.Type==JTokenType.Null?string.Empty:token.ToString();}
        private static string SafeUrl(string value){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&(u.Scheme=="https"||u.Scheme=="http")&&string.IsNullOrEmpty(u.UserInfo)&&u.IsDefaultPort&&u.HostNameType==UriHostNameType.Dns&&u.DnsSafeHost.Contains('.')?u.AbsoluteUri:null;}
        public static string Render(PriceResearchResult result){
            if(result==null)throw new ArgumentNullException("result");var b=new StringBuilder(65536);
            Styles(b);b.Append("<section class=\"price-report\" aria-label=\"MarketCheck price research\">");
            var subject=result.Comparables.OfType<JObject>().FirstOrDefault(result.IsSubject)??result.RecentComparables.OfType<JObject>().FirstOrDefault(result.IsSubject);
            var vehicle=subject==null?"Vehicle price research":string.Join(" ",new[]{S(subject,"year"),S(subject,"make"),S(subject,"model"),S(subject,"trim")}.Where(s=>s.Length>0));
            b.Append("<header class=\"price-report__hero\"><div><p class=\"price-report__eyebrow\">MARKETCHECK · US USED VEHICLES</p><h1>").Append(E(vehicle)).Append("</h1><p class=\"price-report__identity\">").Append(E(result.Request.Vin)).Append(" <span>·</span> ").Append(E(result.Request.Miles.Value.ToString("N0",Us))).Append(" miles <span>·</span> ZIP ").Append(E(result.Request.Zip)).Append(" <span>·</span> ").Append(result.Request.Radius).Append("-mile requested radius</p></div><div class=\"price-report__prediction\"><span>MarketCheck predicted price</span><strong>").Append(E(Money(result.PredictedPrice))).Append("</strong><small>Independent dealer · supplied mileage</small></div></header>");
            var current=result.Comparables.OfType<JObject>().Where(result.IsLocalCompetitor).ToList();
            var recent=result.RecentComparables.OfType<JObject>().Where(result.IsLocalCompetitor).ToList();
            var prices=current.Select(r=>PriceResearchResult.Number(r["price"])).Where(p=>p.HasValue&&p>0).Select(p=>p.Value).ToList();
            b.Append("<div class=\"price-report__metrics\">");Metric(b,"Current within radius",current.Count.ToString("N0",Us));Metric(b,"Local asking-price mean",Money(prices.Count==0?(decimal?)null:prices.Average()));Metric(b,"Recent within radius",recent.Count.ToString("N0",Us));Metric(b,"Requested radius",result.Request.Radius.ToString("N0",Us)+" miles");b.Append("</div>");
            b.Append("<p class=\"price-report__scope\">Showing competitors within ").Append(result.Request.Radius).Append(" miles of ZIP ").Append(E(result.Request.Zip)).Append(". The subject VIN and listings with unknown or negative distances are excluded. The local asking-price mean uses ").Append(prices.Count.ToString("N0",Us)).Append(" priced current comparables without mileage or condition adjustments. Asking prices are listing observations, not completed sale prices. The MarketCheck prediction is the provider estimate; the full unfiltered response remains available separately in the API response.</p>");
            Table(b,current,"Current comparables within radius",true);
            Table(b,recent,"Recent comparables within radius",false);
            b.Append("<footer>MarketCheck data · Retrieved ").Append(E(result.RequestedAtUtc.ToString("yyyy-MM-dd HH:mm 'UTC'",Us))).Append(" · Prediction uses the supplied VIN, mileage and location. Vehicle condition, history, fees and pricing terms are not independently verified.</footer></section>");return b.ToString();
        }
        private static void Metric(StringBuilder b,string title,string value){b.Append("<div class=\"price-report__metric\"><span>").Append(E(title)).Append("</span><strong>").Append(E(value)).Append("</strong></div>");}
        private static void Table(StringBuilder b,IList<JObject> rows,string title,bool open){
            b.Append("<details class=\"price-report__section\"").Append(open?" open":"").Append("><summary><span>").Append(E(title)).Append("</span><small>").Append(rows.Count.ToString("N0",Us)).Append(" within radius</small></summary>");
            if(rows.Count==0){b.Append("<p class=\"price-report__empty\">No comparables within the requested radius are available in this section.</p></details>");return;}
            b.Append("<div class=\"price-report__table-wrap\"><table><thead><tr><th scope=\"col\">Vehicle / VIN</th><th scope=\"col\">Dealer</th><th scope=\"col\" class=\"number\">Asking price</th><th scope=\"col\" class=\"number\">Mileage</th><th scope=\"col\" class=\"number\">Distance</th><th scope=\"col\" class=\"number\">Days on market</th><th scope=\"col\">Listing</th></tr></thead><tbody>");
            foreach(var row in rows.OrderBy(r=>PriceResearchResult.Distance(r))){
                var distance=PriceResearchResult.Distance(row);var url=SafeUrl(S(row,"vdp_url"));
                b.Append("<tr><td><strong>").Append(E(string.Join(" ",new[]{S(row,"year"),S(row,"make"),S(row,"model"),S(row,"trim")}.Where(s=>s.Length>0)))).Append("</strong><code>").Append(E(S(row,"vin"))).Append("</code></td><td>").Append(E(S(row,"dealer_name"))).Append("</td><td class=\"number price\">").Append(E(Money(PriceResearchResult.Number(row["price"])))).Append("</td><td class=\"number\">").Append(E(N(PriceResearchResult.Number(row["miles"])))).Append("</td><td class=\"number\">").Append(E(N(distance,"N1"))).Append(" mi</td><td class=\"number\">").Append(E(N(PriceResearchResult.Number(row["dom"])))).Append("</td><td>");
                if(url!=null)b.Append("<a class=\"price-report__link\" href=\"").Append(E(url)).Append("\" target=\"_blank\" rel=\"noopener noreferrer\">View listing <span aria-hidden=\"true\">↗</span></a>");b.Append("</td></tr>");
            }
            b.Append("</tbody></table></div></details>");
        }
        private static void Styles(StringBuilder b){b.Append(@"<style>
.price-report{--pr-ink:#eef0f2;--pr-muted:#b2b7bd;--pr-border:#606770;color:var(--pr-ink);font:14px/1.55 'Segoe UI',Arial,sans-serif;background:#484e57;padding:22px;border-radius:16px;box-sizing:border-box;max-width:100%;overflow:hidden}.price-report *{box-sizing:border-box}.price-report__hero{background:linear-gradient(125deg,#393e44,#24282d);color:white;border-radius:13px;padding:28px;display:flex;justify-content:space-between;gap:24px;align-items:center}.price-report__hero h1{font-size:26px;line-height:1.2;margin:6px 0 12px;color:white}.price-report__eyebrow{font-size:10px;letter-spacing:.14em;color:#d9dde1;margin:0;font-weight:700}.price-report__identity{font-size:12px;margin:0;color:#d4d6d9}.price-report__identity span{margin:0 6px;color:#aab0b7}.price-report__prediction{min-width:220px;flex-shrink:0;text-align:right}.price-report__prediction span,.price-report__prediction small{display:block;color:#d4d6d9;font-size:11px}.price-report__prediction strong{font-size:42px;line-height:1.2;letter-spacing:-.03em;display:block;margin:5px 0}.price-report__metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0}.price-report__metric{background:#30343a;border:1px solid var(--pr-border);border-radius:10px;padding:16px}.price-report__metric span{display:block;font-size:11px;color:var(--pr-muted)}.price-report__metric strong{font-size:25px;display:block;margin-top:5px}.price-report__notice{border:1px solid #786b50;background:#403c32;color:#e6d0a0;border-radius:10px;padding:14px 17px;margin:16px 0;font-size:12px}.price-report__notice p{margin:4px 0 0}.price-report__scope{color:var(--pr-muted);font-size:12px}.price-report__section,.price-report__raw{background:#30343a;border:1px solid var(--pr-border);border-radius:11px;overflow:hidden;margin:15px 0}.price-report summary{cursor:pointer;list-style-position:inside;padding:16px 18px;font-weight:700}.price-report summary small{font-weight:400;color:var(--pr-muted);margin-left:10px}.price-report__table-wrap{overflow:auto;border-top:1px solid var(--pr-border);max-height:650px}.price-report table{width:100%;border-collapse:collapse;min-width:900px;font-size:12px}.price-report th{text-align:left;background:#626970;color:#f0f2f4;font-size:10px;letter-spacing:.03em;text-transform:uppercase;position:sticky;top:0;padding:12px 14px;white-space:nowrap;z-index:1}.price-report td{border-bottom:1px solid #4d535c;padding:13px 14px;vertical-align:top}.price-report tbody tr:nth-child(even){background:#363b42}.price-report td strong{display:block;font-size:12px;white-space:nowrap}.price-report code{font-size:10px;color:var(--pr-muted);display:block;margin-top:3px;white-space:nowrap}.price-report .number{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.price-report .price{font-weight:700}.price-report__badge{display:block;width:max-content;max-width:100%;border-radius:4px;padding:2px 6px;font-size:9px;font-weight:600;margin-bottom:5px;white-space:nowrap}.price-report__badge.local{background:#33483e;color:#bdd7c6}.price-report__badge.outside{background:#514537;color:#f0d39c}.price-report__badge.subject{background:#55323a;color:#f3c2cc}.price-report__link{color:#f4c2cc;text-decoration:none;white-space:nowrap;font-size:11px}.price-report__link:hover{text-decoration:underline}.price-report__empty{padding:0 18px 18px;color:var(--pr-muted)}.price-report__raw pre{font:11px/1.5 Consolas,monospace;margin:0;padding:16px 18px;max-height:400px;overflow:auto;background:#272c31;border-top:1px solid var(--pr-border);white-space:pre-wrap;overflow-wrap:anywhere}.price-report footer{font-size:10px;color:var(--pr-muted);padding:6px 2px}.price-report tr[data-subject=true]{box-shadow:inset 3px 0 #c41e3a}@media(max-width:700px){.price-report{padding:12px}.price-report__hero{padding:20px;display:block}.price-report__hero h1{font-size:22px}.price-report__prediction{text-align:left;margin-top:20px}.price-report__prediction strong{font-size:36px}.price-report__metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.price-report__metric{padding:12px}.price-report summary small{display:block;margin:4px 0 0 15px}}
</style>");}
    }
}
